// These questions share a short source, but require different readings of it.
function schoolCase(key, passage, questions) {
  for (const [prompt, correct, second, third, explanation] of questions) {
    schoolExample(key, passage + '\n\n' + prompt, correct, [second, third], explanation);
  }
}

